//! One real funded BUY under an independently reviewed runtime capability.
//! Hashes bind provenance; they do not authenticate human/contract/model claims.
//! Runtime must prove original physical attempt closure from its durable log.
use super::*;
impl Engine{
 // Positive native ownership evidence, not queue absence. Runtime must also
 // prove original ACK+complete terminal closure and the approved review/cohort.
 fn reviewed_top_up_state(&self,p:&Value,ex:&str,market:&str,side:Side)->Result<(u64,i128,u64)>{
  if p.as_object().is_none_or(|o|o.len()!=8)||p["version"]!=1{return Err("REVIEWED_ENTRY_TOP_UP_SCHEMA")}
  for k in ["cohortSha256","positionsSha256"]{if p[k].as_str().is_none_or(|s|s.len()!=64||!s.bytes().all(|b|b.is_ascii_digit()||(b'a'..=b'f').contains(&b))){return Err("REVIEWED_ENTRY_TOP_UP_PROOF")}}
  let entries=p["priorEntries"].as_array().ok_or("REVIEWED_ENTRY_TOP_UP_ENTRIES")?;
  let cap=p["maximumEntries"].as_u64().filter(|n|(2..=16).contains(n)).ok_or("REVIEWED_ENTRY_TOP_UP_ENTRIES")?;
  if entries.is_empty()||entries.len()>=cap as usize{return Err("REVIEWED_ENTRY_TOP_UP_ENTRIES")}
  let total=p["maximumTotalQuantity"].as_u64().filter(|n|*n>0&&*n<=10000).ok_or("REVIEWED_ENTRY_TOP_UP_CAP")?;
  let mut ids=BTreeSet::new();let mut previous=0;
  for row in entries{let id=row["qid"].as_u64().filter(|n|*n>previous).ok_or("REVIEWED_ENTRY_TOP_UP_ENTRIES")?;previous=id;
   if row.as_object().is_none_or(|o|o.len()!=3)||!ids.insert(id){return Err("REVIEWED_ENTRY_TOP_UP_ENTRIES")}
   let q=self.orders.iter().find(|q|q.id==id).ok_or("REVIEWED_ENTRY_TOP_UP_ORDER")?;
   if q.exchange!=ex||q.market!=market||q.side!=side||!q.buy||!q.retired||self.is_package_order(id)
    ||self.live_orders.get(&id).is_none_or(|actual|row["actualOrderId"]!=*actual)||row["filledQuantity"].as_u64()!=Some(q.filled){return Err("REVIEWED_ENTRY_TOP_UP_ORDER")}
  }
  let mut lots=Vec::new();let mut held=0u64;let mut cost=0i128;let mut quantities:BTreeMap<u64,u64>=BTreeMap::new();
  for f in &self.fills{let Some(id)=f["orderId"].as_u64().filter(|id|ids.contains(id))else{continue};
   let n=f["quantity"].as_u64().filter(|n|*n>0).ok_or("REVIEWED_ENTRY_TOP_UP_FILL")?;let price=dec(&f["price"])?;
   if f["counterfactual"]!=false||f["exchangeId"]!=ex||f["marketId"]!=market||f["side"]!=label(side)||f["action"]!="buy"||!f["executedAt"].is_string()
    ||self.live_orders.get(&id).is_none_or(|actual|f["actualOrderId"]!=*actual){return Err("REVIEWED_ENTRY_TOP_UP_FILL")}
   held=held.checked_add(n).ok_or("REVIEWED_ENTRY_RANGE")?;cost=cost.checked_add(price.checked_mul(n as i128).ok_or("REVIEWED_ENTRY_RANGE")?).ok_or("REVIEWED_ENTRY_RANGE")?;
   let q=quantities.entry(id).or_default();*q=q.checked_add(n).ok_or("REVIEWED_ENTRY_RANGE")?;
   lots.push(json!({"quantity":n,"price":f["price"],"executedAt":f["executedAt"]}));
  }
  for row in entries{let id=row["qid"].as_u64().ok_or("REVIEWED_ENTRY_TOP_UP_ENTRIES")?;if row["filledQuantity"].as_u64()!=Some(quantities.get(&id).copied().unwrap_or(0)){return Err("REVIEWED_ENTRY_TOP_UP_FILL")}}
  let positions=&self.wallet.positions()[ex];
  if held==0||held>=total||self.wallet.quantity(ex,side.other())!=0||self.wallet.quantity(ex,side)!=held||self.wallet.market_cost(ex)!=cost
   ||positions[label(side)]!=json!(lots)||hash(positions)!=p["positionsSha256"]||p["heldQuantity"].as_u64()!=Some(held)||dec(&p["heldCost"])?!=cost{return Err("REVIEWED_ENTRY_TOP_UP_OWNERSHIP")}
  Ok((held,cost,total))
 }
 pub(super) fn reserve_reviewed_fundamental_entry(&mut self,e:&Value,at:i64)->Result<()>{
  if !self.live_mode||e["source"]!="moloch_live_dispatcher"{return Err("REVIEWED_ENTRY_SOURCE")}
  let ex=id(&e["exchangeId"])?;let market=id(&e["marketId"])?;let tournament=string(&e["bankScope"]["tournamentId"])?;
  let side=match e["side"].as_str(){Some("YES")=>Side::Yes,Some("NO")=>Side::No,_=>return Err("REVIEWED_ENTRY_SIDE")};
  for key in ["originSha256","reviewSha256","bookSha256"]{if e[key].as_str().is_none_or(|s|s.len()!=64||!s.bytes().all(|b|b.is_ascii_digit()||(b'a'..=b'f').contains(&b))){return Err("REVIEWED_ENTRY_PROOF")}}
  if !self.policy.entry(&ex,at){return Err("REVIEWED_ENTRY_DEADLINE")}
  let top_up=match e.get("sameSideTopUp"){None=>None,Some(proof)=>Some(self.reviewed_top_up_state(proof,&ex,&market,side)?)};
  if (top_up.is_none()&&(self.wallet.quantity(&ex,Side::Yes)!=0||self.wallet.quantity(&ex,Side::No)!=0))||self.package_protects_exchange(&ex)||self.package_blocks_submissions()
   ||self.orders.iter().any(|q|q.exchange==ex&&!q.retired)||self.inherited.as_ref().is_some_and(|i|i.remaining.iter().any(|((x,_),lots)|x==&ex&&!lots.is_empty())){return Err("REVIEWED_ENTRY_EXISTING_EXPOSURE")}
  let limit=price(dec(&e["limitPrice"])?)?;let payout=dec(&e["expectedPayout"])?;let margin=dec(&e["marginPerShare"])?;
  let principal=dec(&e["reviewMaximumPrincipal"])?;let maximum=e["reviewMaximumQuantity"].as_u64().filter(|n|*n>0&&*n<=9_007_199_254_740_991).ok_or("REVIEWED_ENTRY_REVIEW_CAP")?;
  if !(0..=SCALE).contains(&payout)||margin<0||margin>SCALE||principal<=0||limit.checked_add(self.policy.fee(limit,1)?).and_then(|n|n.checked_add(margin)).is_none_or(|n|n>payout){return Err("REVIEWED_ENTRY_VALUE")}
  // Mode omission preserves the original join-bid transition and metadata.
  // These hashes bind a runtime-reviewed proposal, not a calibrated forecast
  // or a venue execution guarantee. Ordinary maker generation is unaffected.
  let mode=match e.get("executionMode"){None=>"joinBid",Some(v)=>v.as_str().ok_or("REVIEWED_ENTRY_EXECUTION_MODE")?};
  if !matches!(mode,"joinBid"|"improveOneTick"|"boundedLimitMayRest"){return Err("REVIEWED_ENTRY_EXECUTION_MODE")}
  let extended=mode!="joinBid";
  let ceiling=if extended{
   for key in ["modelSha256","sourceSha256"]{if e[key].as_str().is_none_or(|s|s.len()!=64||!s.bytes().all(|b|b.is_ascii_digit()||(b'a'..=b'f').contains(&b))){return Err("REVIEWED_ENTRY_EXECUTION_PROOF")}}
   let ceiling=price(dec(&e["acquisitionCeiling"])?)?;
   if limit>ceiling||ceiling.checked_add(margin).is_none_or(|n|n>payout)
    ||limit.checked_add(self.policy.fee(limit,1)?).is_none_or(|n|n>=payout){return Err("REVIEWED_ENTRY_EXECUTION_VALUE")}
   Some(ceiling)
  }else{None};
  let review_until=e["reviewCurrentUntilMs"].as_i64().filter(|t|*t>at).ok_or("REVIEWED_ENTRY_REVIEW_EXPIRED")?;
  let expires=ms(&e["expiresAt"])?;
  if expires<=at.checked_add(self.policy.latency).ok_or("REVIEWED_ENTRY_CLOCK")?||expires-at>self.policy.lifetime||expires>review_until||self.policy.stop.is_some_and(|end|expires>end){return Err("REVIEWED_ENTRY_CLOCK")}
  let b=self.books.get(&ex).ok_or("REVIEWED_ENTRY_BOOK")?;
  if b.market!=market||b.tournament!=tournament||!b.fresh(&self.policy,at)||hash(&b.raw)!=e["bookSha256"]{return Err("REVIEWED_ENTRY_BOOK")}
  let bid=if side==Side::Yes{b.bids.first().map(|l|l.0)}else{b.asks.first().map(|l|SCALE-l.0)};
  let ask=if side==Side::Yes{b.asks.first().map(|l|l.0)}else{b.bids.first().map(|l|SCALE-l.0)};
  match mode{
   "joinBid"=>if bid!=Some(limit)||ask.is_none_or(|p|limit>=p){return Err("REVIEWED_ENTRY_PASSIVE_PRICE")},
   "improveOneTick"=>if bid.and_then(|p|p.checked_add(TICK))!=Some(limit)||ask.is_none_or(|p|limit>=p){return Err("REVIEWED_ENTRY_IMPROVE_PRICE")},
   _=>if ask.is_none_or(|p|limit<p){return Err("REVIEWED_ENTRY_BOUNDED_PRICE")},
  }
  // Current same-side executable liquidation depth bounds the entire entry;
  // this is capacity, not a promise of future execution, value or profit.
  // New modes use present bid-side liquidation CAPACITY independently of the
  // acquisition price. Selling it can lose money; no same-price exit is implied.
  let mut depth=0u64;for(yes,n)in if side==Side::Yes{&b.bids}else{&b.asks}{let p=if side==Side::Yes{*yes}else{SCALE-*yes};if extended||p>=limit{depth=depth.checked_add(*n).ok_or("REVIEWED_ENTRY_RANGE")?;}}
  if mode=="boundedLimitMayRest"{
   let mut acquisition=0u64;for(yes,n)in if side==Side::Yes{&b.asks}else{&b.bids}{let p=if side==Side::Yes{*yes}else{SCALE-*yes};if p<=limit{acquisition=acquisition.checked_add(*n).ok_or("REVIEWED_ENTRY_RANGE")?;}}
   depth=depth.min(acquisition);
  }
  let reserved=self.wallet.reserved()?;let cash=self.wallet.cash.checked_sub(reserved).ok_or("REVIEWED_ENTRY_RANGE")?;
  let committed=self.policy.committed.checked_sub(self.wallet.owned_cost()).and_then(|n|n.checked_sub(reserved)).ok_or("REVIEWED_ENTRY_RANGE")?;
  let mut market_used=self.wallet.market_cost(&ex);for q in self.orders.iter().filter(|q|q.exchange==ex&&!q.retired&&q.buy){market_used=market_used.checked_add(self.policy.unit(q.limit)?.checked_mul(q.remaining()as i128).ok_or("REVIEWED_ENTRY_RANGE")?).ok_or("REVIEWED_ENTRY_RANGE")?;}
  let market_left=self.policy.market.checked_sub(market_used).ok_or("REVIEWED_ENTRY_RANGE")?;
  let (principal,maximum)=if let Some((held,cost,total))=top_up{(principal.checked_sub(cost).ok_or("REVIEWED_ENTRY_TOP_UP_CAP")?,maximum.min(total.checked_sub(held).ok_or("REVIEWED_ENTRY_TOP_UP_CAP")?))}else{(principal,maximum)};
  let unit=self.policy.unit(limit)?;let available=principal.min(cash).min(committed).min(market_left);if available<unit{return Err("REVIEWED_ENTRY_FUNDING")}
  let n=maximum.min(self.policy.quantity).min(depth).min(u64::try_from((available/unit).min(u64::MAX as i128)).map_err(|_|"REVIEWED_ENTRY_RANGE")?);if n==0{return Err("REVIEWED_ENTRY_DEPTH")}
  let mut markets=BTreeSet::new();for((exchange,_),lots)in &self.wallet.lots{if !lots.is_empty(){markets.insert(exchange.clone());}}for q in self.orders.iter().filter(|q|!q.retired){markets.insert(q.exchange.clone());}
  if !markets.contains(&ex)&&markets.len()>=self.policy.markets{return Err("REVIEWED_ENTRY_MARKET_CAP")}
  if let Some(i)=&self.inherited{let inherited=|exchange:&String|i.remaining.iter().any(|((x,_),lots)|x==exchange&&!lots.is_empty());if !(top_up.is_some()&&markets.contains(&ex))&&!inherited(&ex)&&markets.iter().filter(|x|!inherited(x)).count()>=i.fresh_market_limit{return Err("REVIEWED_ENTRY_FRESH_MARKET_CAP")}}
  self.writes.retain(|t|at-*t<60000);if self.writes.len()>=self.policy.writes||self.writes.last().is_some_and(|t|at-*t<self.policy.write_gap){return Err("REVIEWED_ENTRY_WRITE_BUDGET")}
  let qid=self.prior_orders+self.orders.len()as u64+1;let(same,better)=Self::visible(b,side,true,limit);
  self.wallet.reserve(&qid.to_string(),Reservation{exchange:ex.clone(),side,quantity:n,limit})?;
  self.orders.push(Order{id:qid,market,exchange:ex,tournament,side,buy:true,quantity:n,filled:0,limit,created:at,activation:at+self.policy.latency,expires,cancel:None,retired:false,credit:0,barrier:None,same,better,visible_same:same,visible_better:better,touch_remainder:0,aon:false,age_reason:false,through:false,participation:100,conditional:false,touch_bps:0});
  self.reviewed_fundamental_entries.insert(qid,json!({"originSha256":e["originSha256"],"reviewSha256":e["reviewSha256"],"bookSha256":e["bookSha256"],"reviewMaximumQuantity":maximum,"reviewMaximumPrincipal":money(dec(&e["reviewMaximumPrincipal"])?),"expectedPayout":money(payout),"marginPerShare":money(margin),"reviewCurrentUntilMs":review_until,"reservedQuantity":n,"grossLimitPrincipal":money(limit*n as i128)}));
  if top_up.is_some(){self.reviewed_fundamental_entries.get_mut(&qid).ok_or("REVIEWED_ENTRY_TOP_UP_METADATA")?["sameSideTopUp"]=e["sameSideTopUp"].clone();}
  if extended{let metadata=self.reviewed_fundamental_entries.get_mut(&qid).ok_or("REVIEWED_ENTRY_EXECUTION_METADATA")?;
   metadata["executionMode"]=json!(mode);metadata["modelSha256"]=e["modelSha256"].clone();metadata["sourceSha256"]=e["sourceSha256"].clone();metadata["acquisitionCeiling"]=json!(money(ceiling.ok_or("REVIEWED_ENTRY_EXECUTION_METADATA")?));
   metadata["actionSpec"]=json!({"marketId":e["marketId"],"exchangeId":e["exchangeId"],"tournamentId":e["bankScope"]["tournamentId"],"side":label(side),"action":"buy","quantity":n,"limitPrice":money(limit)});
  }
  self.writes.push(at);self.count("reviewedFundamentalEntryReservations");Ok(())
 }
}
#[cfg(test)]mod tests{
 use super::*;use crate::session::Session;use std::{path::PathBuf,fs};
 const BASE:i64=1_792_054_800_000;
 fn iso(t:i64)->String{chrono::DateTime::from_timestamp_millis(BASE+t).unwrap().to_rfc3339_opts(chrono::SecondsFormat::Millis,true)}
 struct F{root:PathBuf,bank:Option<Session>,policy:Value,seed:Value}
 impl Drop for F{fn drop(&mut self){self.bank.take();let _=fs::remove_dir_all(&self.root);}}
 impl F{
  fn new(changes:Value)->Self{static NEXT:std::sync::atomic::AtomicU64=std::sync::atomic::AtomicU64::new(0);let root=std::env::temp_dir().join(format!("reviewed-entry-{}-{}-{}",std::process::id(),std::time::SystemTime::now().duration_since(std::time::UNIX_EPOCH).unwrap().as_nanos(),NEXT.fetch_add(1,std::sync::atomic::Ordering::Relaxed)));fs::create_dir(&root).unwrap();let mut policy=json!({"initialCash":"100.000000","maximumCommitted":"20.000000","maximumMarketCost":"10.000000","quantity":100,"maximumMarkets":3,"minimumSpreadTicks":10,"requireCurrentFlow":true,"entryStopAt":iso(120000)});for(k,v)in changes.as_object().unwrap(){policy[k]=v.clone();}let seed=json!({"runId":"reviewed-entry-fixture","availableCash":"100.000000","accountSnapshotHash":"a".repeat(64),"observedAt":iso(0)});let mut bank=Session::open_live(&root.join("bank"),&policy,&seed).unwrap();bank.accept("books",1,&json!({"type":"book","receivedAt":iso(0),"book":{"marketId":"201","exchangeId":"101","tournamentId":"cup","sequence":"1","sourceAt":iso(0),"requestStartedAt":iso(0),"receivedAt":iso(0),"bids":[{"price":"0.400000","quantity":100}],"asks":[{"price":"0.405000","quantity":100}]}})).unwrap();Self{root,bank:Some(bank),policy,seed}}
  fn b(&self)->&Session{self.bank.as_ref().unwrap()}
  fn event(&self)->Value{json!({"type":"reviewed_fundamental_entry_reserved_v1","source":"moloch_live_dispatcher","bankScope":{"runId":"reviewed-entry-fixture","bankManifestHash":self.b().manifest_hash(),"tournamentId":"cup"},"bankHead":self.b().durable_head(),"expectedReportSha256":hash(&self.b().engine().report().unwrap()),"originSha256":"a".repeat(64),"reviewSha256":"b".repeat(64),"bookSha256":hash(&self.b().engine().live_package_books()[0]),"reviewCurrentUntilMs":BASE+120000,"marketId":"201","exchangeId":"101","side":"YES","limitPrice":"0.400000","expectedPayout":"0.600000","marginPerShare":"0.010000","reviewMaximumQuantity":5,"reviewMaximumPrincipal":"1.100000","expiresAt":iso(60000),"receivedAt":iso(3000),"processedAt":iso(3000)})}
  fn reserve(&mut self,e:&Value)->std::result::Result<bool,Box<dyn std::error::Error>>{let seq=self.b().last_source_sequence("reviewed")+1;self.bank.as_mut().unwrap().accept("reviewed",seq,e)}
 }
 #[test]fn reserves_real_capped_single_buy_without_pair_flow_or_minimum_spread(){let mut f=F::new(json!({}));assert!(f.b().engine().order_records().is_empty());let before=f.b().engine().wallet.cash;let e=f.event();f.reserve(&e).unwrap();let qs=f.b().engine().order_records();assert_eq!(qs.len(),1);let q=&qs[0];assert_eq!(q["action"],"buy");assert_eq!(q["side"],"YES");assert_eq!(q["quantity"],2);assert_eq!(q["activationAt"],BASE+6000);assert_eq!(q["reviewedFundamentalEntry"]["reservedQuantity"],2);assert_eq!(f.b().engine().wallet.reserved().unwrap(),800000);assert_eq!(f.b().engine().wallet.cash,before);assert!(f.b().engine().fills().is_empty());}
 #[test]fn derives_quantity_from_total_market_cash_and_review_quantity_bounds(){for(key,value,expected)in[("maximumCommitted","0.500000",1),("maximumMarketCost","0.500000",1),("initialCash","0.500000",1),("quantity","1",1)]{let v=if key=="quantity"{json!(1)}else{json!(value)};let mut changes=json!({});changes[key]=v;let mut f=F::new(changes);let e=f.event();f.reserve(&e).unwrap();assert_eq!(f.b().engine().order_records()[0]["quantity"],expected,"{key}");}}
 #[test]fn exact_session_head_report_and_book_bindings_reject_stale_plans_without_mutation(){for case in ["head","run","report","book","review","price","expiry","source"]{let mut f=F::new(json!({}));let mut e=f.event();match case{"head"=>e["bankHead"]["previous"]=json!("0".repeat(64)),"run"=>e["bankScope"]["runId"]=json!("foreign"),"report"=>e["expectedReportSha256"]=json!("0".repeat(64)),"book"=>e["bookSha256"]=json!("0".repeat(64)),"review"=>e["reviewCurrentUntilMs"]=json!(BASE+3000),"price"=>e["limitPrice"]=json!("0.405000"),"expiry"=>e["expiresAt"]=json!(iso(6000)),_=>e["source"]=json!("untrusted")};let head=f.b().durable_head();let report=f.b().engine().report().unwrap();assert!(f.reserve(&e).is_err(),"{case}");assert_eq!(f.b().durable_head(),head);assert_eq!(f.b().engine().report().unwrap(),report);}}
 #[test]fn ordinary_ticks_never_add_opposite_pair_or_cancel_reviewed_quote(){let mut f=F::new(json!({}));let e=f.event();f.reserve(&e).unwrap();f.bank.as_mut().unwrap().accept("tick",1,&json!({"type":"tick","receivedAt":iso(6000)})).unwrap();let qs=f.b().engine().order_records();assert_eq!(qs.len(),1);assert_eq!(qs[0]["retired"],false);assert!(qs[0].get("cancelEffectiveAt").is_none());assert_eq!(f.b().engine().wallet.reserved().unwrap(),800000);}
 #[test]fn second_unresolved_same_exchange_entry_cannot_replace_or_double_fund(){let mut f=F::new(json!({}));let e=f.event();f.reserve(&e).unwrap();let mut next=f.event();next["processedAt"]=json!(iso(6000));next["receivedAt"]=json!(iso(6000));let head=f.b().durable_head();assert!(f.reserve(&next).is_err());assert_eq!(f.b().durable_head(),head);assert_eq!(f.b().engine().wallet.reserved().unwrap(),800000);}
 #[test]fn full_executable_bid_depth_clips_quantity_and_stale_book_denies(){let mut f=F::new(json!({}));let mut raw=f.b().engine().live_package_books()[0].clone();raw["sequence"]=json!("2");raw["bids"][0]["quantity"]=json!(1);f.bank.as_mut().unwrap().accept("books",2,&json!({"type":"book","receivedAt":iso(0),"book":raw})).unwrap();let e=f.event();f.reserve(&e).unwrap();assert_eq!(f.b().engine().order_records()[0]["quantity"],1);let mut stale=F::new(json!({}));let mut e=stale.event();e["receivedAt"]=json!(iso(11000));e["processedAt"]=json!(iso(11000));assert!(stale.reserve(&e).is_err());}
 #[test]fn unrelated_ordinary_draft_reservations_are_funded_before_reviewed_entry(){let mut f=F::new(json!({"requireCurrentFlow":false,"maximumCommitted":"1.000000"}));let mut raw=f.b().engine().live_package_books()[0].clone();raw["marketId"]=json!("202");raw["exchangeId"]=json!("102");raw["asks"][0]["price"]=json!("0.800000");f.bank.as_mut().unwrap().accept("other-book",1,&json!({"type":"book","receivedAt":iso(0),"book":raw})).unwrap();assert!(f.b().engine().order_records().iter().any(|q|q["exchangeId"]=="102"&&q["retired"]==false));let reserved=f.b().engine().wallet.reserved().unwrap();assert!(reserved>0&&reserved<=1_000_000);let expected=(1_000_000-reserved)/400_000;let e=f.event();let head=f.b().durable_head();if expected==0{assert!(f.reserve(&e).is_err());assert_eq!(f.b().durable_head(),head);assert_eq!(f.b().engine().wallet.reserved().unwrap(),reserved);}else{f.reserve(&e).unwrap();let q=f.b().engine().order_records().into_iter().find(|q|q["exchangeId"]=="101"&&q.get("reviewedFundamentalEntry").is_some()).unwrap();assert_eq!(q["quantity"],expected as u64);assert_eq!(f.b().engine().wallet.reserved().unwrap(),reserved+expected*400_000);}}
 #[test]fn managed_market_cap_includes_other_active_reviewed_reservation(){let mut f=F::new(json!({"maximumMarkets":1}));let mut raw=f.b().engine().live_package_books()[0].clone();raw["marketId"]=json!("202");raw["exchangeId"]=json!("102");f.bank.as_mut().unwrap().accept("other-book",1,&json!({"type":"book","receivedAt":iso(0),"book":raw.clone()})).unwrap();let mut other=f.event();other["marketId"]=json!("202");other["exchangeId"]=json!("102");other["bookSha256"]=json!(hash(&raw));f.reserve(&other).unwrap();let mut e=f.event();e["processedAt"]=json!(iso(6000));e["receivedAt"]=json!(iso(6000));let before=f.b().durable_head();assert!(f.reserve(&e).is_err());assert_eq!(f.b().durable_head(),before);}
 #[test]fn actual_ack_partial_fill_terminal_and_restart_preserve_real_accounting_only(){let mut f=F::new(json!({}));let e=f.event();f.reserve(&e).unwrap();let q=f.b().engine().order_records()[0].clone();let base=json!({"source":"official_sig_api_v1","receiptHash":"c".repeat(64),"orderId":q["id"],"actualOrderId":"901","marketId":"201","exchangeId":"101","side":"YES","action":"buy","price":"0.400000","receivedAt":iso(6000),"executedAt":iso(6000),"fee":"0.000000","quantity":2});let mut ack=base.clone();ack["type"]=json!("actual_order_ack");f.bank.as_mut().unwrap().accept("official",1,&ack).unwrap();assert!(f.b().engine().fills().is_empty());assert_eq!(f.b().engine().wallet.cash,100_000_000);let mut fill=base.clone();fill["type"]=json!("actual_fill");fill["quantity"]=json!(1);fill["fillId"]=json!("701");f.bank.as_mut().unwrap().accept("official",2,&fill).unwrap();assert_eq!(f.b().engine().wallet.cash,99_600_000);assert_eq!(f.b().engine().wallet.quantity("101",Side::Yes),1);assert_eq!(f.b().engine().wallet.reserved().unwrap(),400000);let mut terminal=base;terminal["type"]=json!("actual_order_terminal");terminal["status"]=json!("canceled");terminal["filledQuantity"]=json!(1);terminal["fillsComplete"]=json!(true);f.bank.as_mut().unwrap().accept("official",3,&terminal).unwrap();assert_eq!(f.b().engine().wallet.reserved().unwrap(),0);let report=f.b().engine().report().unwrap();let orders=f.b().engine().order_records();let head=f.b().durable_head();f.bank.take();let bank=Session::open_live(&f.root.join("bank"),&f.policy,&f.seed).unwrap();assert_eq!(bank.engine().report().unwrap(),report);assert_eq!(bank.engine().order_records(),orders);assert_eq!(bank.durable_head(),head);assert_eq!(bank.engine().fills().len(),1);}
 impl F{
  fn mode(&mut self,mode:&str,side:&str,limit:&str)->Value{
   let mut raw=self.b().engine().live_package_books()[0].clone();raw["sequence"]=json!("2");raw["bids"]=json!([{"price":"0.400000","quantity":4},{"price":"0.395000","quantity":20}]);raw["asks"]=json!([{"price":"0.420000","quantity":2},{"price":"0.430000","quantity":3},{"price":"0.450000","quantity":20}]);
   self.bank.as_mut().unwrap().accept("books",2,&json!({"type":"book","receivedAt":iso(0),"book":raw})).unwrap();
   let mut e=self.event();e["executionMode"]=json!(mode);e["side"]=json!(side);e["limitPrice"]=json!(limit);e["modelSha256"]=json!("d".repeat(64));e["sourceSha256"]=json!("e".repeat(64));e["acquisitionCeiling"]=json!(if side=="YES"{"0.450000"}else{"0.650000"});e["expectedPayout"]=json!("0.900000");e["reviewMaximumPrincipal"]=json!("10.000000");e["reviewMaximumQuantity"]=json!(20);e
  }
 }
 #[test]fn modes_improved_entry_does_not_require_liquidation_bid_at_acquisition_price(){let mut f=F::new(json!({}));let e=f.mode("improveOneTick","YES","0.405000");f.reserve(&e).unwrap();let q=&f.b().engine().order_records()[0];assert_eq!(q["price"],"0.405000");assert_eq!(q["quantity"],20);assert_eq!(q["reviewedFundamentalEntry"]["executionMode"],"improveOneTick");assert_eq!(q["reviewedFundamentalEntry"]["actionSpec"]["quantity"],20);assert_eq!(f.b().engine().wallet.reserved().unwrap(),8_100_000);assert!(f.b().engine().fills().is_empty());}
 #[test]fn modes_bounded_buy_uses_all_ask_levels_within_frozen_limit(){let mut f=F::new(json!({}));let e=f.mode("boundedLimitMayRest","YES","0.430000");f.reserve(&e).unwrap();let q=&f.b().engine().order_records()[0];assert_eq!(q["quantity"],5);assert_eq!(q["reviewedFundamentalEntry"]["grossLimitPrincipal"],"2.150000");assert_eq!(f.b().engine().wallet.cash,100_000_000);assert_eq!(f.b().engine().wallet.reserved().unwrap(),2_150_000);assert!(f.b().engine().fills().is_empty());}
 #[test]fn modes_no_side_complements_both_acquisition_and_liquidation_depth(){for(mode,limit,n)in[("improveOneTick","0.585000",17),("boundedLimitMayRest","0.605000",16)]{let mut f=F::new(json!({}));let e=f.mode(mode,"NO",limit);f.reserve(&e).unwrap();let q=&f.b().engine().order_records()[0];assert_eq!(q["side"],"NO");assert_eq!(q["price"],limit);assert_eq!(q["quantity"],n);assert_eq!(q["reviewedFundamentalEntry"]["actionSpec"]["side"],"NO");}}
 #[test]fn modes_full_frozen_price_funding_not_weighted_depth_clips_quantity(){let mut f=F::new(json!({}));let mut e=f.mode("boundedLimitMayRest","YES","0.430000");e["reviewMaximumPrincipal"]=json!("2.100000");f.reserve(&e).unwrap();assert_eq!(f.b().engine().order_records()[0]["quantity"],4);assert_eq!(f.b().engine().wallet.reserved().unwrap(),1_720_000);}
 #[test]fn modes_native_caps_apply_to_aggressive_reservations(){for(key,val)in[("maximumCommitted",json!("0.500000")),("maximumMarketCost",json!("0.500000")),("initialCash",json!("0.500000")),("quantity",json!(1))]{let mut p=json!({});p[key]=val;let mut f=F::new(p);let e=f.mode("boundedLimitMayRest","YES","0.430000");f.reserve(&e).unwrap();assert_eq!(f.b().engine().order_records()[0]["quantity"],1,"{key}");}}
 #[test]fn modes_bad_mode_ceiling_provenance_and_value_fail_atomically(){for case in ["unknown","null","model","source","ceiling_low","ceiling_value","zero_value","improve_cross","bounded_passive"]{let mut f=F::new(json!({}));let mut e=f.mode("boundedLimitMayRest","YES","0.430000");match case{"unknown"=>e["executionMode"]=json!("market"),"null"=>e["executionMode"]=Value::Null,"model"=>{e.as_object_mut().unwrap().remove("modelSha256");},"source"=>e["sourceSha256"]=json!("untrusted"),"ceiling_low"=>e["acquisitionCeiling"]=json!("0.425000"),"ceiling_value"=>e["acquisitionCeiling"]=json!("0.900000"),"zero_value"=>{e["expectedPayout"]=json!("0.430000");e["marginPerShare"]=json!("0.000000");e["acquisitionCeiling"]=json!("0.430000");},"improve_cross"=>{e["executionMode"]=json!("improveOneTick");e["limitPrice"]=json!("0.420000");},_=>e["limitPrice"]=json!("0.405000")};let head=f.b().durable_head();let report=f.b().engine().report().unwrap();assert!(f.reserve(&e).is_err(),"{case}");assert_eq!(f.b().durable_head(),head);assert_eq!(f.b().engine().report().unwrap(),report);}}
 #[test]fn modes_omission_and_explicit_join_preserve_old_metadata_and_financials(){let mut a=F::new(json!({}));let mut b=F::new(json!({}));let ea=a.event();let mut eb=b.event();eb["executionMode"]=json!("joinBid");a.reserve(&ea).unwrap();b.reserve(&eb).unwrap();assert_eq!(a.b().engine().order_records(),b.b().engine().order_records());assert_eq!(a.b().engine().report().unwrap(),b.b().engine().report().unwrap());assert!(a.b().engine().order_records()[0]["reviewedFundamentalEntry"].get("executionMode").is_none());}
 #[test]fn modes_stale_or_gap_book_cannot_reserve_despite_positive_forecast(){for gap in [false,true]{let mut f=F::new(json!({}));let mut e=f.mode("boundedLimitMayRest","YES","0.430000");if gap{f.bank.as_mut().unwrap().accept("gap",1,&json!({"type":"gap","receivedAt":iso(1000),"exchangeIds":["101"],"reason":"fixture"})).unwrap();e["bankHead"]=f.b().durable_head();e["expectedReportSha256"]=json!(hash(&f.b().engine().report().unwrap()));}else{e["receivedAt"]=json!(iso(11000));e["processedAt"]=json!(iso(11000));}assert!(f.reserve(&e).is_err());assert!(f.b().engine().fills().is_empty());}}
 #[test]fn modes_generated_action_and_review_provenance_survive_ticks_and_restart(){let mut f=F::new(json!({}));let e=f.mode("boundedLimitMayRest","YES","0.430000");f.reserve(&e).unwrap();f.bank.as_mut().unwrap().accept("tick",1,&json!({"type":"tick","receivedAt":iso(6000)})).unwrap();let q=f.b().engine().order_records()[0].clone();assert_eq!(q["retired"],false);assert!(q.get("cancelEffectiveAt").is_none());assert_eq!(q["reviewedFundamentalEntry"]["modelSha256"],"d".repeat(64));let report=f.b().engine().report().unwrap();f.bank.take();let bank=Session::open_live(&f.root.join("bank"),&f.policy,&f.seed).unwrap();assert_eq!(bank.engine().order_records()[0],q);assert_eq!(bank.engine().report().unwrap(),report);assert!(bank.engine().fills().is_empty());}
 #[test]fn modes_marketable_reservation_is_not_atomic_fill_or_ack_profit(){let mut f=F::new(json!({}));let e=f.mode("boundedLimitMayRest","YES","0.430000");f.reserve(&e).unwrap();let q=f.b().engine().order_records()[0].clone();let mut official=json!({"type":"actual_order_ack","source":"official_sig_api_v1","receiptHash":"c".repeat(64),"orderId":q["id"],"actualOrderId":"901","marketId":"201","exchangeId":"101","side":"YES","action":"buy","price":"0.430000","quantity":5,"receivedAt":iso(6000),"executedAt":iso(6000),"fee":"0.000000"});f.bank.as_mut().unwrap().accept("official",1,&official).unwrap();assert_eq!(f.b().engine().wallet.cash,100_000_000);assert!(f.b().engine().fills().is_empty());official["type"]=json!("actual_fill");official["quantity"]=json!(1);official["fillId"]=json!("701");f.bank.as_mut().unwrap().accept("official",2,&official).unwrap();assert_eq!(f.b().engine().wallet.cash,99_570_000);assert_eq!(f.b().engine().wallet.quantity("101",Side::Yes),1);assert_eq!(f.b().engine().wallet.reserved().unwrap(),1_720_000);official["type"]=json!("actual_order_terminal");official["quantity"]=json!(5);official["status"]=json!("canceled");official["filledQuantity"]=json!(1);official["fillsComplete"]=json!(true);f.bank.as_mut().unwrap().accept("official",3,&official).unwrap();assert_eq!(f.b().engine().wallet.reserved().unwrap(),0);assert_eq!(f.b().engine().wallet.quantity("101",Side::Yes),1);assert_eq!(f.b().engine().wallet.realized,0);}
}
